14	const (
15		// MaxMentionLength matches the username token length accepted by the API.
16		MaxMentionLength = 32
17	)
18	
19	type mentionParser struct{}
20	
21	// NewMentionParser creates a new inline parser for @mention syntax.
22	func NewMentionParser() parser.InlineParser {
23		return &mentionParser{}
24	}
25	
26	// Trigger returns the characters that trigger this parser.
27	func (*mentionParser) Trigger() []byte {
28		return []byte{'@'}
29	}
30	
31	func isValidMentionRune(r rune) bool {
32		return unicode.IsLetter(r) || unicode.IsNumber(r) || r == '-'
33	}
34	
35	func isMentionBoundary(r rune) bool {
36		return unicode.IsSpace(r) || unicode.IsPunct(r) || unicode.IsSymbol(r)
37	}
38	
39	// Parse parses @mention syntax while avoiding email-address matches.
40	func (*mentionParser) Parse(_ gast.Node, block text.Reader, _ parser.Context) gast.Node {
41		line, _ := block.PeekLine()
42		if len(line) == 0 || line[0] != '@' {
43			return nil
44		}
45	
46		prev := block.PrecendingCharacter()
47		if prev != '\n' && !isMentionBoundary(prev) {
48			return nil
49		}
50	
51		start := 1
52		pos := start
53		runeCount := 0
54		hasLetterOrNumber := false
55	
56		for pos < len(line) {
57			r, size := utf8.DecodeRune(line[pos:])
58			if r == utf8.RuneError && size == 1 {
59				break
60			}
61			if !isValidMentionRune(r) {
62				break
63			}
64			if unicode.IsLetter(r) || unicode.IsNumber(r) {
65				hasLetterOrNumber = true
66			}
67			runeCount++
68			if runeCount > MaxMentionLength {
69				break
70			}
71			pos += size
72		}
73	
74		if pos <= start || !hasLetterOrNumber {
75			return nil
76		}
77	
78		username := line[start:pos]
79		usernameCopy := make([]byte, len(username))
80		copy(usernameCopy, username)
81	
82		block.Advance(pos)
83	
84		return &mast.MentionNode{
85			Username: usernameCopy,
86		}
87	}
